{
  "query": "SELECT Id, CaseNumber, Status, Severity__c, Outstanding_Reserve__c, Policy__r.Id, Policy__r.Name, Policy__r.Expiration_Date__c, Account.Name FROM Case WHERE RecordType.DeveloperName = 'Claim' AND IsClosed = false AND Policy__r.Expiration_Date__c >= TODAY AND Policy__r.Expiration_Date__c <= NEXT_N_DAYS:90 ORDER BY Policy__r.Expiration_Date__c LIMIT 50"
}
